161	/**
162	 * Welche Rechte braucht eine Admin-API? Liefert [{ bereich, stufe }] (alle müssen erfüllt sein).
163	 * `body` wird für Status/Zuweisung (Objektart) und Aufgaben mit Bezug ausgewertet.
164	 */
165	export function apiAnforderungen({ pfad, methode = "GET", body, params = {}, recht } = {}) {
166	  const schreiben = !["GET", "HEAD", "OPTIONS"].includes(String(methode).toUpperCase());
167	  const teile = String(pfad || "").split("?")[0].split("/").filter(Boolean); // ["api","admin",teil,…]
168	  const teil = teile[2] || "";
169	  const st = schreiben ? 2 : 1;
170	  if (recht) return [].concat(recht).map((r) => (typeof r === "string" ? { bereich: r, stufe: st } : r));
171	  if (teil === "status" || teil === "zuweisen") {
172	    return [{ bereich: BEREICH_FUER_ART[body?.art] || "sonstiges", stufe: 2 }];
173	  }
174	  if (teil === "export") {
175	    const art = params?.art || teile[3];
176	    return [{ bereich: "export", stufe: 1 }, { bereich: BEREICH_FUER_ART[art] || "sonstiges", stufe: 1 }];
177	  }
178	  if (teil === "berichte") return [{ bereich: "berichte", stufe: 1 }]; // PDF/CSV-Abruf ist Lesen
179	  const anf = [{ bereich: API_BEREICH[teil] || "sonstiges", stufe: st }];
180	  if (teil === "aufgaben" && schreiben && body?.bezugArt && BEREICH_FUER_ART[body.bezugArt]) {
181	    anf.push({ bereich: BEREICH_FUER_ART[body.bezugArt], stufe: 1 });
182	  }
183	  if (teil === "automationen" && teile[3] === "testlauf") anf[0].stufe = 1; // Testlauf ändert nichts
184	  if (teil === "vorlagen" && teile[3] === "vorschau") anf[0].stufe = 1;
185	  return anf;
186	}
187	
188	/** Fehlende Rechte (leer = erlaubt) */
189	export function fehlendeRechte(n, anforderungen) {
190	  return anforderungen.filter((a) => stufe(n, a.bereich) < a.stufe);
191	}
