// Rendern einer Portalseite laufen – awaited fs.promises-Rückgaben landen sonst im Dev-HTML (docs/BRIEFING.md).

import { mkdirSync, readFileSync, rmSync, writeFileSync } from "node:fs";
import path from "node:path";
