const BETREFF = { signatur: "Elektronische Unterschrift – ÖkoInvest", termin: "Ihr Termin – ÖkoInvest", ticket: "Ihre Support-Anfrage – ÖkoInvest", aufgabe: "Zuweisung im Backoffice – ÖkoInvest" };

