  { frage: "Wie verschiebe oder storniere ich einen Termin?", antwort: "In der Bestätigungs-E-Mail finden Sie einen persönlichen Link. Darüber können Sie den Termin bis zum Beginn verschieben oder absagen. Mit einem Portal-Konto sehen Sie Ihre Termine zusätzlich unter „Termine“." },
  { frage: "Was sollte ich für eine Flächenbesichtigung vorbereiten?", antwort: "Hilfreich sind Flurstücksnummern oder ein Lageplan, bekannte Leitungen oder Dienstbarkeiten und – falls vorhanden – Angaben zum Pachtstatus. Eine erste Einschätzung erhalten Sie in der Regel schon vorab über den Flächencheck." },
];

export default async function TerminSeite({ searchParams }) {
  const sp = await searchParams;
  const arten = TERMIN_ART_IDS.filter((a) => TERMIN_ARTEN[a].oeffentlich);
  const herkunft = HERKUNFT.includes(sp?.herkunft) ? sp.herkunft : "website";
  const schema = {
    "@context": "https://schema.org",
    "@type": "Service",
    name: "Terminbuchung ÖkoInvest",
    url: abs(PFAD),
    provider: { "@id": `${abs("/")}/#organization` },
    areaServed: ["DE", "AT", "CH"],
    availableChannel: { "@type": "ServiceChannel", serviceUrl: abs(PFAD) },
  };
  return (
    <div>
      <script type="application/ld+json" dangerouslySetInnerHTML={{ __html: JSON.stringify(schema) }} />
