// Datenraum-Session nur für Investoren). Mitarbeiter werden nur dem Backoffice genannt.
import { route } from "@/lib/plattform/server/route";
import { serviceBackend } from "@/lib/plattform/backend/service";

export const GET = route({ auth: "optional", limit: "nachricht" }, async ({ nutzer, suche }) => {
  try {
    return { ok: true, ...(await serviceBackend().terminSlots(nutzer, { art: suche.get("art") || "", von: suche.get("von") || "", bis: suche.get("bis") || "", mitarbeiterId: suche.get("mitarbeiter") || "" })) };
  } catch (e) {
    if (process.env.NODE_ENV !== "production" && !e?.status) return { ok: false, debug: String(e?.stack || e).slice(0, 1500) }; // TEMP-DEBUG
    throw e;
  }
});

